//////////--------------------------------------------------------------------------------------------------------------=
 typedef enum logic [1:0] {
        IDLE       = 2'b00,
        SHOW_WIN   = 2'b01,
        SHOW_LOST  = 2'b10
    } draw_state_t;

    draw_state_t current_state, next_state;

    // === State Transition Logic ===
    always_comb begin
        case (current_state)
            IDLE: begin
                if (win)
                    next_state = SHOW_WIN;
                else if (lost)
                    next_state = SHOW_LOST;
                else
                    next_state = IDLE;
            end
            SHOW_WIN:  next_state = SHOW_WIN;   // Stay in win forever
            SHOW_LOST: next_state = SHOW_LOST;  // Stay in lose forever
            default:   next_state = IDLE;
        endcase
    end

    // === State Register ===
    always_ff @(posedge clk or negedge resetN) begin
        if (!resetN)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // === Pixel Rendering ===
    always_ff @(posedge clk or negedge resetN) begin
        if (!resetN) begin
            RGBout <= 8'h00;
        end else begin
            RGBout <= TRANSPARENT_ENCODING;  // Default to transparent

            if (InsideRectangle) begin
                case (current_state)
                    SHOW_WIN:  RGBout <= object_colors[0][offsetY][offsetX];
                    SHOW_LOST: RGBout <= object_colors[1][offsetY][offsetX];
                    default:   RGBout <= TRANSPARENT_ENCODING;
                endcase
				end
			end 
		end
//////////--------------------------------------------------------------------------------------------------------------=
// decide if to draw the pixel or not 
assign drawingRequest = (RGBout != TRANSPARENT_ENCODING) ? 1'b1 : 1'b0 ; // get optional transparent command from the bitmpap   

endmodule  